// Expanded beginner courses for SkillBridge.
// Each lesson is written to teach a usable skill, with an applied activity,
// a visual explanation, and three questions tied to the lesson.
const quiz = (items) => items.map(([q, correct, distractorA, distractorB], index) => ({
  q,
  options: [correct, distractorA, distractorB, "Skip the check and submit immediately"],
  answer: 0,
  why: correct + ". This matters because reliable work follows the lesson's process and checks the result."
}));
const lesson = (title, text, practice, steps, questions, caption) => ({
  title, videoId: "", text, practice,
  diagram: { type: "flow", title: caption || "Put the idea into practice", steps: steps.map(([label, note]) => ({ label, note })) },
  quiz: quiz(questions)
});
const job = (name, url, note, cta = "Explore opportunities") => ({ name, url, note, cta });

export const extraCourses = [
  {
    slug: "spreadsheet-skills-for-beginners", title: "Spreadsheet Skills for Beginners", category: "Data & Research", level: "Beginner", minutes: 240, duration: "About 4 hours, plus practice", summary: "Learn to structure, calculate, clean, check, and explain spreadsheet data through realistic work tasks.",
    modules: [
      lesson("What a spreadsheet is—and when to use one", `A spreadsheet is a digital grid for storing information and working with it. It is useful when you need to keep records, compare options, calculate totals, or spot patterns. A shop might use one to track stock; a community group might use one to manage registrations; a freelancer might use one to track invoices. A spreadsheet is not automatically a database or a source of truth: the quality of its results depends on the information and rules entered into it.\n\nA workbook is the whole file. A worksheet is one tab inside it. Rows run horizontally and usually represent records, such as one customer or one order. Columns run vertically and hold fields, such as date, customer name, quantity, or price. A cell is one box where a row and column meet. Its address combines a column letter and row number, such as B3.\n\nBefore creating a sheet, ask: what decision or task should this information support? Then identify one row's meaning and choose a column for each field. If a table mixes several kinds of information in one cell, it becomes harder to sort, filter, and calculate accurately.`, "Create a five-row table of imaginary orders. Use one row per order and separate columns for order ID, date, item, quantity, and status. Explain what one row represents.", [["Purpose", "What question must the sheet answer?"],["Rows", "One consistent record per row"],["Columns", "One kind of information per column"],["Review", "Check that the structure supports the task"]], [["What should a row usually represent in an order table?", "One order record", "All information mixed together", "A different field each time"],["What is a cell address such as B3?", "A column and row location", "The name of the workbook", "A formula result only"],["Why plan the table before entering lots of data?", "A consistent structure makes checking and analysis easier", "Formatting is more important than meaning", "It removes the need to check information"]], "Build a clear table"),
      lesson("Design a table that stays understandable", `Good spreadsheets are designed for the next person who must use them, not just for the person who created them. Give every column a short, specific heading. “Date paid” is more useful than “Date” when the sheet contains several dates. Avoid blank rows inside a data table because they can interrupt sorting, filtering, and selecting a full range. Keep one type of information in each column: do not put a person's name and phone number in the same cell if you may need to search them separately.\n\nUse a unique identifier when possible. Two customers may share a name, but a customer ID can distinguish their records. Decide how dates, phone numbers, currency, and status values should be written before entering data. For example, if some dates use DD/MM/YYYY and others use MM/DD/YYYY, a reader may misinterpret them. Phone numbers should generally be treated as identifiers, not numbers for arithmetic, because leading zeros can matter.\n\nKeep raw source data separate from summaries or calculations when practical. This makes it easier to compare the original information with any cleaned or transformed version. Add a short note explaining unusual abbreviations or rules. A tidy structure reduces errors later; it does not merely make the sheet look attractive.`, "Improve a badly designed table by proposing headings, a unique ID, one consistent date format, and a way to keep the original data safe.", [["Name each field", "Use clear, specific headings"],["Standardize", "Choose one format for each kind of value"],["Separate", "Keep different fields in different columns"],["Protect the source", "Retain an original copy before cleaning"]], [["Why use a unique customer ID?", "It distinguishes records even when names match", "It makes every name shorter", "It replaces all other useful fields"],["Why should phone numbers often be stored as text?", "Leading zeros and formatting may matter", "Phone numbers are always added together", "Text automatically verifies the number"],["What is a good practice before cleaning important data?", "Keep an untouched original copy", "Delete the original immediately", "Remove headings to save space"]], "Structure before scale"),
      lesson("Enter and format data consistently", `Data entry is not simply typing quickly. It means putting the correct value in the correct field and following the agreed format. If one status is written as “Paid,” another as “paid,” and another as “complete,” a filter may treat them as different values even when they mean the same thing. Agree on an approved list such as Pending, Paid, and Cancelled, then use those labels consistently.\n\nFormatting helps people interpret data. Dates should look like dates, currency should use the appropriate number format, and quantities should be numeric when calculations are required. Avoid typing currency symbols into every amount if the spreadsheet can format the cells; the underlying values should remain usable for calculations. Formatting changes how a value appears, while the stored value is what formulas use. A number that looks like a date may still be stored as text, so check the value if calculations fail.\n\nUse data validation when available to limit entries to approved choices or ranges. It can prevent some errors, but it cannot guarantee truth: a selected customer name may still be wrong. After entering a batch, compare a sample against the source and check for blank required fields, unexpected formats, and accidental duplicates.`, "Create a status column with three approved values. Enter sample dates and prices, format them consistently, and identify one way formatting can hide a data-entry problem.", [["Agree", "Define valid values and formats"],["Enter", "Put each value in its intended field"],["Format", "Make dates, amounts, and labels consistent"],["Validate", "Check required fields and unusual entries"]], [["What is the difference between a value and its formatting?", "The value is stored data; formatting controls its display", "They are always identical concepts", "Formatting proves the value is correct"],["What does a controlled status list help prevent?", "Inconsistent labels and some invalid entries", "Every possible human error", "The need for review"],["After entering a batch, what should you do?", "Compare samples and check missing or unusual values", "Assume the software caught every mistake", "Delete the source documents"]], "From entry to quality check"),
      lesson("Use formulas and cell references", `A formula tells a spreadsheet to calculate something. In common spreadsheet tools, formulas begin with an equals sign. For example, if quantity is in B2 and unit price is in C2, ` + "`=B2*C2`" + ` calculates the line total. ` + "`=SUM(D2:D6)`" + ` adds the values in cells D2 through D6. Formulas are useful because the result can update when the input values change.\n\nA cell reference points to a cell. Relative references adjust when a formula is copied, which is often helpful when calculating each row's total. Absolute references, written with dollar signs such as ` + "`$B$1`" + `, stay fixed when copied. This is useful when every row needs to use one tax rate or exchange rate stored in a single cell. Do not memorize formulas without understanding which cells they refer to.\n\nCheck formulas with a small example you can calculate by hand. If three items cost 2, 5, and 3, the total should be 10. If a formula returns an unexpected answer, inspect the referenced cells, the range boundaries, and whether values are numbers or text. A spreadsheet can calculate a wrong formula perfectly, so the person preparing the sheet remains responsible for verifying it.`, "Create quantity, unit-price, and line-total columns for four imaginary items. Write a formula for one line, copy it down, calculate the grand total, and verify one result by hand.", [["Identify inputs", "Know which cells contain the quantities and prices"],["Write formula", "Use the correct operators and references"],["Copy carefully", "Check that references shift as intended"],["Verify", "Compare a sample with a hand calculation"]], [["What does `=B2*C2` do when B2 is quantity and C2 is unit price?", "Multiplies quantity by unit price", "Adds the worksheet names", "Counts every blank cell"],["Why use an absolute reference such as `$B$1`?", "To keep a reference fixed when copying a formula", "To erase the value in B1", "To turn text into a verified fact"],["Why check a formula using a small hand calculation?", "A formula can be syntactically valid but refer to the wrong cells", "Spreadsheets cannot do arithmetic", "Manual checks make the formula unnecessary"]], "Think in inputs and outputs"),
      lesson("Use common functions for everyday work", `A function is a ready-made operation that performs a common calculation. SUM adds values; AVERAGE calculates the arithmetic mean; MIN and MAX return the smallest and largest values; COUNT counts numeric cells; COUNTA counts non-empty cells. For example, ` + "`=AVERAGE(C2:C11)`" + ` can calculate the average of ten scores. The range must include the intended records and exclude headings or unrelated values.\n\nFunctions answer specific questions, and the question should guide the choice. If you want the total of sales, use SUM. If you want to know how many numeric entries were recorded, COUNT may help. If you want to count all non-empty customer-name cells, COUNTA is more appropriate. Neither count automatically tells you whether the entries are valid or unique.\n\nAverages can be misleading when values vary widely or when records are missing. Imagine four daily sales totals of 10, 10, 10, and 70. The average is 25, but three of the four days were only 10. Report the average with enough context and inspect unusual values. A useful analyst does not merely produce a number; they explain what it does and does not tell the reader.`, "Use a small list of six sales amounts. Calculate the sum, average, minimum, and maximum. Write one sentence explaining a limitation of the average.", [["Ask the question", "What do you need to know?"],["Choose a function", "SUM, AVERAGE, MIN, MAX, COUNT, or COUNTA"],["Select the range", "Include the right records"],["Interpret", "Explain the result in context"]], [["Which function adds values in a range?", "SUM", "AVERAGE", "COUNTA"],["When is COUNTA useful?", "Counting non-empty cells such as filled name cells", "Finding the smallest numeric value", "Adding all amounts"],["Why should an average be interpreted carefully?", "A few unusual values can change it substantially", "It always shows the most common value", "It proves every record is accurate"]], "Choose the function that answers the question"),
      lesson("Sort and filter without losing records", `Sorting changes the order of rows according to a field, such as date, amount, or name. Filtering temporarily hides rows that do not meet selected conditions. For example, you could filter a list to show only orders marked Pending, or sort invoices from oldest to newest. These tools help you find information in a long list without deleting the records you are not currently viewing.\n\nThe most important safety rule is to sort the complete table, not one column by itself. If you sort names without moving the matching phone numbers and IDs, the relationships between fields break. Before sorting, confirm that the full range is selected and that headings are recognized. After sorting, check a few records to ensure their related fields stayed together.\n\nFilters can also hide rows, so a total calculated on the visible screen may not mean what you think it means. Know whether the formula includes hidden records. Remove or clear filters before concluding that records are missing. If you are unsure, make a copy first and practise with sample data. Sorting and filtering are reversible views of your data when used correctly, but they can create serious confusion if applied carelessly.`, "Make ten sample orders with different dates and statuses. Filter for Pending orders, then sort the full table by date. Verify that the order ID still matches each customer and amount.", [["Prepare", "Confirm headings and select the full table"],["Apply", "Choose the field and condition"],["Inspect", "Check that related values stayed together"],["Clear", "Remove filters before final review"]], [["What does a filter normally do?", "Shows records matching a condition while hiding others", "Permanently deletes all unmatched records", "Changes every value into text"],["Why should you sort the whole table?", "Related fields must stay on the same record", "Only names matter in a table", "Sorting a single column is always safer"],["What should you do if records seem to be missing after filtering?", "Check and clear the filter", "Delete the hidden rows", "Assume the data has vanished"]], "Find records without damaging relationships"),
      lesson("Clean messy data systematically", `Messy data may contain extra spaces, inconsistent capitalization, duplicate records, missing values, spelling differences, or numbers stored as text. Cleaning means improving consistency while preserving the meaning of the original information. Begin by making a copy and identifying the rules for what counts as valid. Do not start deleting values simply because they look unusual; an unusual value may be correct.\n\nWork through one problem type at a time. Trim extra spaces, standardize approved labels, check date formats, and look for duplicates using appropriate fields. Two rows with the same name are not necessarily duplicates; they may be different people. A duplicate decision should consider the record's unique identifier or several matching fields. Missing values should be marked or investigated according to the task rules, not filled with guesses.\n\nKeep a short change log for important cleaning work: what was changed, why, and how uncertain cases were handled. Recheck totals and record counts before and after the process. If 500 records become 430, you should know whether 70 duplicates were legitimately removed or whether rows were accidentally lost. Cleaning is not about making data look neat at any cost; it is about making it more dependable and explainable.`, "Prepare a messy sample with extra spaces, mixed status labels, one missing value, and two possible duplicates. Write a cleaning plan before making changes, and identify which duplicate needs further investigation.", [["Copy", "Preserve the untouched source"],["Profile", "Find blanks, odd formats, and repeated values"],["Clean by rule", "Standardize only when meaning is clear"],["Reconcile", "Compare counts and record changes"]], [["Why preserve the original before cleaning?", "It allows comparison and recovery if a change is wrong", "It guarantees all values are correct", "It makes the cleaning rules unnecessary"],["Are two rows with the same name always duplicates?", "No; compare identifiers and other relevant fields", "Yes, delete one immediately", "Only if the rows have different dates"],["What should happen to an unknown missing value?", "Investigate or mark it according to agreed rules, not guess", "Invent a likely value", "Copy the value from a random row"]], "Clean with rules, not guesses"),
      lesson("Check accuracy and deliver a professional file", `Quality checking is part of the task, not an optional final glance. Use the source document to verify high-risk fields such as names, amounts, account numbers, dates, and IDs. Recheck totals, required fields, duplicate warnings, and unusual values. A useful method is to check every critical field and then sample other records systematically. For a small dataset, checking every row may be reasonable; for a large one, follow the client's specified quality process and document the sample.\n\nBefore delivery, confirm that the file has a clear name, useful headings, readable formatting, and no accidental personal information in hidden tabs or comments. Save it in the requested format and location. If the client requests a spreadsheet file, do not silently send a screenshot or PDF instead. If you find an unresolved issue, state it clearly rather than hiding it.\n\nA professional handover tells the recipient what is included, what checks were performed, and what still needs attention. For example: “I entered 126 records, checked all invoice totals, standardized the date format, and flagged three rows where the source was unreadable.” This is more useful than saying only “Done.” It shows care without claiming that no error is possible.`, "Create a final checklist for a small data-entry task. Include source comparison, required fields, totals, duplicate review, file name, format, and a concise handover note.", [["Check source", "Verify important fields against the original"],["Check structure", "Review missing fields, totals, and duplicates"],["Prepare file", "Use a clear name and requested format"],["Hand over", "Report completed checks and unresolved issues"]], [["What is a good handover note?", "A concise summary of work, checks, and unresolved issues", "A claim that the work is perfect without evidence", "A message that hides missing information"],["What should you do with an unreadable source value?", "Flag it for clarification instead of inventing it", "Guess based on nearby rows", "Delete the entire dataset"],["Why check the requested file format?", "The recipient needs a usable deliverable in the agreed format", "File format never affects usability", "A screenshot always replaces a spreadsheet"]], "Deliver work another person can trust")
    ],
    jobs: [job("We Work Remotely", "https://weworkremotely.com/remote-jobs", "Explore listings and check each employer and role carefully.", "Browse jobs")]
  },
  {
    slug: "social-media-management-basics", title: "Social Media Management Basics", category: "Marketing & Media", level: "Beginner", minutes: 260, duration: "About 4 hours, plus practice", summary: "Learn to plan useful content, understand an audience, publish responsibly, manage conversations, and interpret results.",
    modules: [
      lesson("What a social media manager actually does", `Social media management is the planned work of communicating with a specific audience on digital platforms. It can include researching audience needs, setting goals, planning content, writing captions, preparing visuals, scheduling approved posts, replying to comments, escalating problems, and reporting results. It is not simply posting as often as possible. A busy account can still be ineffective if its content is irrelevant or its replies are careless.\n\nThe role depends on the client or organization. A local bakery may want nearby people to discover its products and opening hours. A nonprofit may want to explain a service and help people access it. A software company may need clear educational posts and careful support responses. The audience, objective, tone, and risk level are different in each case.\n\nA beginner should clarify responsibilities before accepting work: which accounts they may access, what content they can approve, which topics need client approval, how quickly they should respond, and what they must never publish. Passwords should not be shared casually. Use platform roles or approved access methods where available, enable account security, and never promise viral growth or sales that cannot be guaranteed.`, "Write a short role agreement for a small business. Include platforms, posting frequency, approval rules, reply responsibilities, access security, and what is outside your scope.", [["Understand the organization", "Products, services, audience, and risks"],["Agree responsibilities", "Content, approvals, replies, and reporting"],["Protect access", "Use approved roles and account security"],["Review results", "Measure outcomes against agreed goals"]], [["Why is social media management more than frequent posting?", "Content must serve an audience and a clear goal", "Posting frequency guarantees sales", "Replies and safety do not matter"],["What should a beginner clarify before managing an account?", "Responsibilities, approvals, access, and escalation rules", "Only the preferred emoji", "Nothing; every brand works the same way"],["Which claim is responsible?", "We can test content and report results, but cannot guarantee virality", "I guarantee a million views", "I can publish anything without approval"]], "Understand the job before doing the job"),
      lesson("Understand the audience and set a goal", `A useful post begins with a person and a purpose. “Everyone on social media” is not a useful audience definition. Think about who needs the information, what they already know, what questions they have, and what action would help them. For a neighbourhood bakery, the audience may be people within delivery distance who need to know today's menu or how to order. For a training organization, it may be beginners comparing learning options.\n\nA goal describes the result you want, such as awareness, useful conversations, customer support, website visits, registrations, or sales inquiries. Choose a goal before choosing a format. If the goal is to answer a common question, a clear explainer may be better than a promotional graphic. If the goal is to help people find a location, opening hours and directions should be easy to see.\n\nMake goals specific enough to review. “Get more engagement” is vague. “Increase meaningful comments on the next four educational posts” is more focused, although you still need to define what counts as meaningful and compare results fairly. Do not confuse a metric with the goal itself: likes may be easy to count, but they do not automatically prove trust, sales, or understanding.`, "Choose a real or imaginary small business. Define one audience, one audience need, one content goal, and one metric that can help you assess progress.", [["Audience", "Who specifically needs this?"],["Need", "What question or problem do they have?"],["Goal", "What useful outcome should the post support?"],["Metric", "What evidence can indicate progress?"]], [["What is wrong with defining the audience as everyone?", "It gives little guidance for relevant content", "It is always more accurate", "It guarantees reach"],["Which is a clearer goal?", "Help nearby customers find today's opening hours", "Make the account famous", "Post something attractive"],["Do likes automatically prove business success?", "No; choose measures that fit the goal", "Yes, every like is a sale", "Yes, comments and clicks never matter"]], "Audience first, content second"),
      lesson("Build a content plan and calendar", `A content calendar turns ideas into an organized schedule. Useful columns include date, platform, audience, topic, format, goal, draft caption, visual needed, owner, approval status, and link to the final asset. The calendar helps the manager see whether content is balanced, whether deadlines are realistic, and whether posts repeat the same message too often.\n\nPlan around audience needs rather than filling every day with promotional material. A simple mix might include education, product or service information, behind-the-scenes material, customer questions, and community stories where permission has been given. The right mix depends on the organization; there is no universal ratio that guarantees success. Leave space for timely updates and ensure urgent public information is checked before publishing.\n\nA calendar is a plan, not permission to publish without review. Mark each post as draft, awaiting approval, approved, scheduled, published, or postponed. Confirm dates, time zones, links, prices, claims, and image rights. If a fact changes, update the scheduled content rather than letting an outdated post go live. After publishing, record the live link and any useful observation for the next planning cycle.`, "Create a one-week calendar with three posts. For each, specify audience, goal, format, approval owner, date, and a check needed before publishing.", [["Plan themes", "Cover useful audience needs"],["Schedule", "Set realistic dates and owners"],["Approve", "Verify claims, links, rights, and timing"],["Learn", "Record results and improve the next plan"]], [["What is a content calendar mainly for?", "Coordinating topics, dates, responsibilities, and approvals", "Guaranteeing every post will perform well", "Replacing all communication with a client"],["Why include approval status?", "It helps prevent an unapproved draft from being published", "It makes every claim true", "It removes the need for a deadline"],["What should happen if a scheduled price is outdated?", "Correct or postpone the post before it goes live", "Publish it because it was already planned", "Hide the issue from the client"]], "Plan content people can rely on"),
      lesson("Write clear captions and useful calls to action", `A caption should help the intended reader understand the message and what to do next. Start with the most useful point, use concrete language, and remove filler. A strong opening is relevant rather than merely dramatic. Avoid exaggerated promises, misleading urgency, and claims that the organization cannot support. If an offer has conditions, make them visible rather than hiding them in vague wording.\n\nA call to action (CTA) is the next step you invite someone to take: read the guide, check the menu, register, ask a question, or visit a page. Choose one primary action when possible. Several competing CTAs can confuse the reader. Make sure the destination works and matches the promise in the caption. If you ask people to register, the link should lead to the correct registration page, not a general homepage where the form is difficult to find.\n\nUse a voice that fits the brand and audience. Friendly does not mean careless; professional does not mean stiff. Read the caption aloud, check spelling and names, and ask whether a person unfamiliar with the business would understand it. Hashtags and emojis can support the message when appropriate, but they cannot rescue unclear content. Adapt length and style to the platform without changing important facts.`, "Write two captions for the same service: one educational and one promotional. Give each a single clear CTA, then check whether every claim can be supported.", [["Lead with value", "Answer a need or explain the benefit"],["Be specific", "Use clear facts and natural language"],["Choose one action", "Make the next step obvious"],["Proofread", "Check names, claims, links, and tone"]], [["What makes a call to action useful?", "It gives the reader a clear, relevant next step", "It asks for every possible action at once", "It hides the destination"],["How should a manager handle a claim they cannot verify?", "Check it or remove/rewrite it before publishing", "Make it more dramatic", "Assume it is true because it sounds good"],["Can hashtags fix an unclear caption?", "No; the main message must already be clear", "Yes, any caption becomes clear with enough tags", "Only if the caption has no goal"]], "Make the next step clear"),
      lesson("Create accessible visuals and work with design briefs", `Social posts are often seen quickly and on small screens. A visual should communicate one main idea and support the caption, not compete with it. Use readable text, strong contrast, sensible spacing, and a clear focal point. If a graphic contains essential information, do not make the text so small that a phone user must zoom to read it. Avoid placing key text too close to the edges where platform cropping may cut it off.\n\nA design brief records the purpose, audience, key message, format or dimensions, brand assets, required wording, deadline, and approval process. It also identifies constraints such as legal disclaimers, accessibility, or image rights. Ask questions when the brief is incomplete. For example, “Make it pop” is not a measurable instruction; ask what the audience should notice first and what action the design should support.\n\nUse images and music only when you have permission or a suitable license. Do not assume an image is free because it appears in a search result. Add descriptive alternative text when the platform supports it, and do not rely on colour alone to communicate meaning. Keep editable source files and use the requested export format so revisions can be made efficiently.`, "Write a design brief for an event announcement. Include audience, key message, format, required details, contrast/readability checks, image permission, and approval.", [["Brief", "Clarify purpose, audience, and required details"],["Design", "Use hierarchy, contrast, and readable text"],["Check access", "Consider mobile reading and alternative text"],["Clear rights", "Use approved assets and retain source files"]], [["What should a social visual usually communicate?", "One clear main idea that supports the post goal", "Every detail in the business plan", "A message unrelated to the caption"],["Why is a design brief important?", "It aligns the design with audience, message, constraints, and approval", "It guarantees everyone will like the design", "It replaces proofreading"],["Can you freely use any image found online?", "No; check permission or licensing", "Yes, search results are public domain", "Yes, if you crop the watermark"]], "Design for real people and real screens"),
      lesson("Schedule, publish, and maintain a reliable workflow", `Scheduling tools can save time, but they do not remove the need for human review. Before scheduling, confirm the platform, account, date, time zone, caption, visual, links, tags, and approval. A correct post sent from the wrong account can still cause harm. Use a checklist, especially when managing multiple clients. Keep a clear record of what was approved and who approved it.\n\nAfter publication, open the live post and check that the image displays correctly, links work, formatting survived, and no text was cut off. If you notice a mistake, follow the agreed correction process promptly. Some errors can be edited; others may require removing the post and publishing a corrected version. Do not quietly delete a serious issue if the client needs to know about it.\n\nProtect accounts and customer information. Use individual access where available, strong unique passwords, and multi-factor authentication. Never put private customer details in public replies or shared planning documents without a legitimate reason. If a suspicious login, compromised account, or accidental disclosure occurs, report it through the agreed escalation route immediately. A reliable workflow protects the audience and the organization, not just the posting schedule.`, "Create a pre-publish and post-publish checklist. Include account, approval, time zone, links, visual, privacy, and live-post checks.", [["Preflight", "Check account, copy, visual, approval, and schedule"],["Publish", "Use the correct platform and account"],["Verify live post", "Check links, crop, formatting, and details"],["Escalate", "Report account or privacy incidents promptly"]], [["Why check a post after it goes live?", "The platform may display links or visuals differently than expected", "Scheduling guarantees the final display", "Live checks are only for large brands"],["What is safer than sharing one account password with a team?", "Use approved individual access and security controls", "Send the password in a public group", "Use the same password for every client"],["What should you do after an accidental disclosure of private information?", "Follow the incident and escalation process promptly", "Ignore it unless someone complains", "Copy the information into more posts"]], "Publish carefully, then verify"),
      lesson("Manage comments, complaints, and difficult conversations", `Community management means responding in a way that is useful, respectful, and consistent with the organization's policy. First identify the type of message: a genuine question, routine complaint, abusive comment, spam, threat, or request involving private account details. Different cases need different actions. A public reply should not reveal a customer's order number, address, health information, or other private details. Invite the person to an approved private support channel when appropriate.\n\nA good complaint response acknowledges the concern without arguing or making promises you cannot keep. For example: “I'm sorry this has been frustrating. Please send us a message through our official support channel so the team can check the order privately.” Do not admit facts you have not verified or blame a colleague in public. If the issue concerns safety, discrimination, legal threats, or a widespread service failure, follow the escalation rules rather than improvising.\n\nModeration should follow a written policy applied consistently. Criticism is not automatically abuse, and deleting every negative comment can damage trust. Remove or report content when it violates the platform or organization's rules, such as threats, targeted harassment, scams, or exposed private information. Keep a record of significant incidents without unnecessarily copying sensitive content.`, "Draft responses to a delayed order complaint, a question about opening hours, and a comment exposing someone's private details. Decide which should be answered publicly, moved to private support, or escalated.", [["Classify", "Question, complaint, abuse, threat, or private issue?"],["Respond", "Acknowledge and give a safe next step"],["Protect", "Keep private details out of public replies"],["Escalate", "Use policy for serious or uncertain cases"]], [["What should a public reply to a private account issue do?", "Direct the person to an approved private support route", "Ask them to post their address publicly", "Publish their account details to prove the point"],["Is every negative comment automatically abuse?", "No; distinguish criticism from policy violations", "Yes; delete all criticism", "Yes, unless it praises the organization"],["What if a message contains a credible threat?", "Follow the safety and escalation policy", "Joke about it publicly", "Promise an outcome without checking"]], "Respond with care and boundaries"),
      lesson("Measure results and improve your next plan", `Metrics are measurements; insights are explanations that connect results to a goal. Reach estimates how many people saw content, impressions count displays, clicks show people took a link action, and comments or saves can indicate different kinds of interaction. Definitions vary by platform, so check what a metric means before comparing reports. Do not compare unlike periods without considering audience size, posting frequency, seasonality, and paid promotion.\n\nChoose a small set of measures that match the objective. If the goal is website visits, link clicks and useful landing-page activity may matter more than likes. If the goal is customer support, response time and whether the question was resolved may be more useful. Numbers alone rarely explain why a post performed as it did. Review the topic, opening, format, timing, audience relevance, and any external events. Treat a single post as a clue, not conclusive proof.\n\nA good report is honest and actionable. State the period, goal, results, limitations, and one or two tests for next time. Avoid claiming that a change caused an outcome when several factors changed together. Protect personal data in reports and share only information the client is entitled to receive. The purpose of measurement is to make better decisions, not to decorate a report with impressive-looking numbers.`, "Write a one-page report for three imaginary posts. State the goal, one relevant metric per post, what the numbers suggest, what they cannot prove, and one next experiment.", [["Set the goal", "Define the result you want to support"],["Choose metrics", "Measure the action relevant to that goal"],["Interpret", "Look for patterns and alternative explanations"],["Test", "Make one sensible improvement and review again"]], [["If the goal is website visits, which metric is directly relevant?", "Link clicks and useful landing-page activity", "The number of decorative emojis", "The length of the caption alone"],["Does one successful post prove a strategy always works?", "No; consider context and test patterns over time", "Yes, one result proves causation", "Yes, metrics never change"],["What should a useful report include?", "Goal, results, limitations, and a practical next step", "Only the most flattering number", "Personal data unrelated to the work"]], "Use evidence to improve, not to exaggerate")
    ],
    jobs: [job("LinkedIn Jobs", "https://www.linkedin.com/jobs/", "Search for junior social media, community, and content assistant roles.", "Search jobs")]
  },
  {
    slug: "beginner-graphic-design", title: "Beginner Graphic Design", category: "Design & Creative", level: "Beginner", minutes: 270, duration: "About 4.5 hours, plus design practice", summary: "Learn to plan a design, organize visual information, choose readable type and colour, work with images, and prepare polished deliverables.",
    modules: [
      lesson("What graphic design does", `Graphic design uses visual choices to communicate a message to a particular audience. A poster may help people notice an event; a product graphic may explain a benefit; an infographic may make a process easier to understand. A design is not successful simply because it looks fashionable. It should make the intended message easier to find, understand, remember, or act on.\n\nStart by identifying the communication problem. Who is the audience? What must they understand? What is the most important information? Where will the design appear—a phone screen, printed flyer, presentation, or website? The answers affect the layout, size, text, image choices, and level of detail. A mobile post often needs fewer words and stronger hierarchy than a full-page handout.\n\nA beginner does not need to master every tool before making useful design decisions. Learn the principles first, then practise them in a tool you can access. Keep a clear distinction between your own work, licensed assets, and references used for inspiration. Never copy another designer's complete work and present it as your own.`, "Choose an imaginary event and write its audience, purpose, main message, delivery format, and the one action viewers should take.", [["Audience", "Who needs to understand the message?"],["Purpose", "What should the design help them do?"],["Context", "Where and how will it be seen?"],["Success", "What should the viewer notice or understand?"]], [["What is the main job of graphic design?", "Communicate a message clearly to an audience", "Add decoration regardless of purpose", "Use as many fonts as possible"],["Why does the delivery format matter?", "It affects size, detail, readability, and layout", "Every design has identical constraints", "It determines whether the message needs to be true"],["How should you use another designer's work?", "Use it for learning or inspiration without claiming it as your own", "Copy it and remove the signature", "Assume online images have no rights"]], "Design begins with communication"),
      lesson("Read a brief and plan before opening the design tool", `A design brief turns a vague request into decisions you can work with. It should identify the audience, objective, key message, required text, format and dimensions, brand colours or logos, deadline, delivery files, and who approves the result. It should also mention accessibility, image rights, language, and any required disclaimer. If information is missing, ask before guessing.\n\nTranslate subjective feedback into specific questions. If someone says “make it pop,” ask what they want people to notice first, what feels too quiet, or which action matters most. If they say “make the logo bigger,” check the brand requirements and the available space. A designer's job includes interpreting needs, but important assumptions should be confirmed rather than hidden.\n\nCreate a simple content hierarchy before styling: the headline, supporting detail, date or price, and call to action may not all have equal importance. Sketch two or three rough layout options. This is faster than polishing one idea and discovering later that the information order is wrong. A short written plan can prevent repeated revisions and protect the deadline.`, "Create a brief for a square community-event graphic. List the exact text, audience, dimensions, brand constraints, deadline, approval person, and three questions you need answered.", [["Collect requirements", "Audience, purpose, format, content, deadline"],["Resolve gaps", "Ask questions about ambiguous instructions"],["Rank information", "Decide what viewers must notice first"],["Sketch", "Compare rough layout options before polishing"]], [["What should you do with an unclear instruction such as 'make it pop'?", "Ask what the viewer should notice and what outcome matters", "Add random effects immediately", "Ignore the client"],["Why sketch rough options first?", "It tests the information order before time is spent polishing", "Sketching guarantees approval", "It replaces the design brief"],["What belongs in a useful brief?", "Audience, objective, exact content, format, deadline, and approval", "Only a colour preference", "Only the designer's favourite style"]], "Turn requests into design decisions"),
      lesson("Create visual hierarchy and guide the eye", `Visual hierarchy is the order in which people notice information. Size, placement, contrast, weight, spacing, and alignment can signal importance. A headline may be larger than supporting details, while a date or call to action may receive a distinct position. If everything is large, bold, colourful, or boxed, nothing stands out. Hierarchy is about making priorities visible, not making every element compete.\n\nThink about the viewer's likely path through the design. On a simple event poster, the eye might move from event name to key benefit, then date and location, and finally registration instructions. The order should match the viewer's questions. A promotion that hides the price or conditions in tiny text may attract attention but fails to communicate responsibly.\n\nUse alignment and spacing to show which elements belong together. Consistent margins make a layout feel intentional. Related details placed close together are easier to interpret than details scattered across the page. Empty space is not wasted space; it separates groups and lets important information breathe. Review the design at its actual viewing size, not only zoomed in on a large screen.`, "Sketch a poster hierarchy using five elements: headline, benefit, date, location, and CTA. Explain the intended reading order and which elements should be visually quiet.", [["Prioritize", "Identify the most important message"],["Emphasize", "Use size, placement, and contrast deliberately"],["Group", "Keep related details close and aligned"],["Test", "Review at the real viewing size"]], [["What happens when every element has maximum emphasis?", "The viewer loses a clear priority", "The design automatically becomes clearer", "The headline becomes easier to identify"],["Why group related details?", "Proximity helps viewers understand which information belongs together", "It hides information from the audience", "It makes alignment unnecessary"],["What is empty space useful for?", "Separating groups and allowing important content to breathe", "Proving the design is unfinished", "Replacing all supporting information"]], "Guide attention with intention"),
      lesson("Use typography for readability and tone", `Typography is the choice and arrangement of text. Different typefaces have different personalities, but readability comes first. Use a typeface that remains clear at the intended size and screen. Body text needs comfortable size, line spacing, and line length. Decorative type may work for a short headline but can become difficult to read in long paragraphs or small labels.\n\nLimit the number of type families and define a consistent role for each style, such as headline, subheading, body, and caption. Contrast these roles through size, weight, and spacing rather than changing every property randomly. Check capital letters, punctuation, spelling, and line breaks. Avoid stretching letters to fit a space; adjust the layout or rewrite the text with approval.\n\nType also affects inclusion. Very small text, low contrast, all-capital paragraphs, and crowded line spacing make content harder to read. Test the design on a typical phone and consider viewers with visual or reading difficulties. If the design must include a long disclaimer, do not shrink it until it is technically present but practically unreadable; revisit the layout and ask whether the content can be organized more clearly.`, "Design a type scale for a poster: headline, supporting heading, body, and small details. State how you will test the smallest text on a phone.", [["Assign roles", "Headline, subheading, body, and details"],["Limit choices", "Use a small consistent type system"],["Check readability", "Size, spacing, contrast, and line length"],["Proofread", "Verify exact wording and line breaks"]], [["Why limit type styles?", "A consistent system creates hierarchy without visual noise", "More fonts always mean more professionalism", "It makes proofreading unnecessary"],["What should you do if required text is unreadable at the current size?", "Rework the layout and clarify requirements", "Shrink it until it barely fits", "Remove it without approval"],["When should body text be tested?", "At the size and device where people will actually read it", "Only at extreme zoom", "Only in the design editor"]], "Typography should serve the reader"),
      lesson("Choose colour and contrast responsibly", `Colour can establish mood, distinguish sections, and help a brand feel consistent. It should support the message rather than be chosen only because a designer likes it. Start with a limited palette: a main colour, supporting colour, neutral background, and an accent when needed. Use colour consistently for similar roles. Too many competing colours can make a design feel fragmented and can weaken hierarchy.\n\nContrast is the difference that makes text or an object distinguishable from its background. Pale text on a pale background may look elegant on a bright monitor but become unreadable on a phone or in sunlight. Check small text especially carefully. Do not rely on colour alone to communicate status—combine colour with a label, icon, pattern, or other cue so people who cannot distinguish the colours can still understand.\n\nConsider context and culture: colour associations vary, and a colour that signals celebration in one context may carry a different meaning elsewhere. Use brand guidance where it exists, but still protect readability. If a design includes a photograph behind text, use a suitable overlay or a simpler area for the words rather than hoping the image will always provide enough contrast.`, "Choose a three-colour palette for an educational poster. Explain the role of each colour and how you will ensure small text stays readable without relying on colour alone.", [["Choose purpose", "What feeling or distinction should colour support?"],["Limit palette", "Assign consistent roles to a few colours"],["Check contrast", "Test text against its actual background"],["Add redundancy", "Use labels or shapes as well as colour"]], [["What is the main purpose of contrast?", "To make important elements distinguishable and readable", "To make every colour equally bright", "To replace content hierarchy"],["Why not use colour alone for status?", "Some viewers may not distinguish the colours", "Colour always communicates identically", "Labels make designs less accessible"],["What should you do with text over a busy photo?", "Create a readable area or overlay and test contrast", "Assume the text will remain clear", "Choose the thinnest font available"]], "Colour choices need a readability check"),
      lesson("Use images, icons, and spacing ethically", `Images can explain, demonstrate, or create emotional context, but they should be relevant to the message. A low-quality or unrelated image can reduce trust. Check crop, resolution, subject placement, and whether the image still makes sense in the intended format. Icons should be familiar or clearly explained; an ambiguous icon may confuse a viewer rather than save space.\n\nImage rights matter. A picture being visible in a search engine does not mean it is free to use. Use your own assets, properly licensed resources, or content with permission, and follow any attribution requirements. Keep records of asset sources and licenses for client work. Be especially careful with photos of identifiable people, private spaces, or sensitive situations. Do not imply that a stock image depicts a real customer or event if it does not.\n\nSpacing and alignment create structure. Use consistent margins and gaps between related elements. Align edges and baselines where appropriate, and check that objects do not sit awkwardly close to the edge. A grid can help position elements, but it should support the content rather than become a rigid rule. Before exporting, inspect the design at full size and thumbnail size: full size reveals details; thumbnail size reveals whether the main message is still recognizable.`, "Create a short asset checklist for a social graphic. Include relevance, resolution, crop, license, attribution, privacy, spacing, and small-screen review.", [["Select", "Choose relevant, clear, suitable assets"],["Verify rights", "Confirm permission, license, and attribution"],["Arrange", "Use alignment, margins, and consistent gaps"],["Inspect", "Check the full-size design and thumbnail"]], [["Does a search result mean an image is free to use?", "No; permission and license still need checking", "Yes, all indexed images are public domain", "Yes, if used for a small business"],["Why check a design as a thumbnail?", "It reveals whether the main idea remains clear at small size", "It proves the file is editable", "It replaces checking the full-size version"],["What is a useful role for spacing?", "Separating groups and creating a clear structure", "Filling every empty area", "Hiding the main message"]], "Use assets with care and purpose"),
      lesson("Design for different formats and accessibility", `A design that works as a square social post may not work as a story, banner, slide, or printed flyer. Each format has different dimensions, viewing conditions, and platform controls. Important text can be cropped by profile grids or interface elements, so keep it within a safe area and preview the final placement. Do not stretch a square graphic into a wide banner; reorganize the hierarchy for the new shape.\n\nAccessibility improves the experience for more people. Use sufficient contrast, readable type, plain language, and meaningful structure. Where possible, provide alternative text that describes the informative content of an image rather than saying “picture.” If a graphic contains detailed information, include the key information in the caption or accompanying text. Avoid flashing effects and do not use colour as the only signal.\n\nExport settings affect quality and usability. Use the format requested by the platform or client, preserve a high-quality source file, and check that text and edges look sharp. A compressed file may load faster but can make small text fuzzy. Confirm dimensions and file size requirements before delivery. When the design is adapted for several formats, check each version individually instead of assuming that one export works everywhere.`, "Adapt a square event design to a vertical story and a wide banner. List what must move, what must remain readable, and how you will check accessibility.", [["Check the destination", "Dimensions, crop, and interface safe areas"],["Recompose", "Rebuild hierarchy for the new shape"],["Make accessible", "Contrast, readable text, and alternative text"],["Export and inspect", "Use the requested format and review every version"]], [["Why shouldn't you simply stretch a square graphic into a banner?", "Stretching can distort elements and damage the information hierarchy", "All formats require identical proportions", "Stretching improves every image"],["What should alternative text do?", "Describe the informative content of the image", "Repeat a random filename", "Replace every visible heading"],["After exporting multiple formats, what should you do?", "Inspect each version at its intended size", "Assume all exports are identical in quality", "Delete the editable source"]], "Design for the actual viewing context"),
      lesson("Revise, export, and present a professional design", `A design review is easier when you compare the result with the original brief. Check whether the main message is obvious, required information is present, hierarchy is clear, text is readable, alignment is consistent, and images are appropriate and licensed. Proofread names, dates, prices, URLs, and disclaimers carefully. A beautiful layout with the wrong date is still a failed deliverable.\n\nFeedback should be turned into specific actions. If a client says “it feels crowded,” identify which elements compete and whether spacing, grouping, or editing the copy could help. If two reviewers disagree, return to the audience and goal rather than treating personal taste as the only standard. Keep track of versions so the latest approved file is clear, and do not overwrite the only editable source.\n\nDeliver the requested formats with clear filenames. Depending on the agreement, the client may need a ready-to-post image, a print-ready PDF, and/or an editable source file. Include a concise handover note stating what is attached and asking for any final factual corrections. Do not claim that the design is guaranteed to increase sales. Explain the decisions you made and be open to reasonable revision within the agreed scope.`, "Create a final review checklist and a handover message for a completed event graphic. Include version naming, factual checks, rights, export format, and the source file.", [["Review against brief", "Purpose, audience, required content, and format"],["Proofread", "Check all facts and small details"],["Version", "Save an editable source and clear final export"],["Handover", "Explain files included and note any open questions"]], [["What is the most important final check on an event poster?", "Verify factual details such as date, location, and registration link", "Check only whether the colours match your mood", "Ignore small text"],["How should conflicting feedback be resolved?", "Return to the brief, audience, and communication goal", "Choose whichever comment is loudest", "Change every element at once"],["What makes a professional handover?", "Clear filenames, requested formats, and a concise note", "An unlabeled folder of drafts", "A promise of guaranteed sales"]], "Finish with care and clear delivery")
    ],
    jobs: [job("Behance JobList", "https://www.behance.net/joblist", "Explore creative opportunities and study portfolio examples.", "Explore opportunities")]
  },
  {
    slug: "web-research-and-fact-checking", title: "Web Research & Fact-Checking Basics", category: "Data & Research", level: "Beginner", minutes: 250, duration: "About 4 hours, plus research practice", summary: "Learn to frame research questions, find and evaluate sources, verify claims, document evidence, and present careful conclusions.",
    modules: [
      lesson("Turn a broad request into answerable questions", `Research begins by understanding the decision or question the work must support. A request such as “research online education” is too broad to guide efficient work. Ask what the requester needs to decide, which audience or location matters, what time period is relevant, and what form the answer should take. A short clarification can prevent hours of collecting information that does not answer the real question.\n\nBreak the request into smaller questions. For example, “Which beginner online courses are suitable for adults in a particular country?” may require checking course topics, price, language, access requirements, certificates, and current availability. Separate essential criteria from useful extras. Define what evidence would count as an answer and what cannot be established from public sources.\n\nCreate a research plan before searching. List the questions, likely source types, key search terms, and a place to record findings. Keep an open mind: research should test the question, not merely collect evidence for a conclusion you already prefer. If the available evidence is incomplete, the honest result may be “not confirmed” rather than a confident answer.`, "Turn a broad request about remote work opportunities into five specific research questions. Identify the time period, location, evidence needed, and any details that must be clarified with the requester.", [["Clarify", "Decision, audience, scope, and time period"],["Break down", "Create answerable sub-questions"],["Plan", "Choose source types and search terms"],["Define limits", "State what evidence can and cannot establish"]], [["Why is a broad request difficult to research?", "It does not define the information needed or what counts as an answer", "It always has too many reliable sources", "It means research is unnecessary"],["What should you do when a key requirement is unclear?", "Ask a focused clarification question", "Guess and present the guess as fact", "Collect unrelated information"],["Is 'not confirmed' sometimes a valid finding?", "Yes, when available evidence does not establish the claim", "No, every report must give a definite answer", "Only if the requester agrees with you"]], "Define the question before searching"),
      lesson("Search strategically and record your process", `Search engines rank pages for many reasons, and the first result is not automatically the best evidence. Use specific search phrases, quotation marks for exact wording when helpful, and filters for date or source type when relevant. Search for the original report, dataset, policy, or announcement rather than relying only on pages that repeat it. For current information, check publication and update dates; an accurate old page may no longer answer a current question.\n\nUse more than one search path. Search the main phrase, a key claim, the organization responsible, and possible alternative wording. If the result is surprising, search for evidence that could disprove it as well as evidence that supports it. Be careful with snippets: they may omit context or combine text from different parts of a page. Open and read the relevant section before recording a claim.\n\nKeep a research log with the question, search terms, source title, publisher, URL, date published or updated, date accessed, relevant finding, and next verification step. This makes your work reproducible and helps you avoid repeatedly visiting the same sources. Do not save only a copied sentence without its context; record enough surrounding information to understand what the source actually says.`, "Create a research-log template and use it to record three sources for one question. Include the search phrase, source date, key finding, and a next step for verification.", [["Search specifically", "Use terms that reflect the actual question"],["Open the source", "Read context instead of relying on snippets"],["Record", "Capture publisher, date, URL, and finding"],["Repeat strategically", "Try alternate wording and disconfirming searches"]], [["Is the first search result automatically the most reliable?", "No; ranking is not the same as evidence quality", "Yes, ranking proves accuracy", "Only if the page has a logo"],["Why record search terms?", "They help explain and reproduce how findings were located", "They guarantee a claim is true", "They replace source evaluation"],["What is a risk of relying on a search snippet alone?", "It may omit context or combine fragments", "It always contains the complete report", "It proves the page is current"]], "Make research traceable"),
      lesson("Evaluate who published a source and why", `Source evaluation asks who created the information, what evidence supports it, when it was produced, and what purpose it serves. A government agency may be authoritative for its own current policy; a peer-reviewed study may be useful for a research question; a company's product page may be best for its published specifications but less independent for claims about its superiority. Reliability depends on the question.\n\nCheck the author's relevant expertise, the publisher's reputation, links to original evidence, methods, funding or conflicts of interest, and whether corrections are documented. Distinguish primary sources—such as original datasets, legal texts, interviews, or official announcements—from secondary summaries that interpret them. Primary sources are not automatically flawless, but reading them can reveal whether a summary has omitted important context.\n\nBe cautious with anonymous claims, sensational headlines, copied content with no original source, and pages that use citations that do not support the statement. A polished design, professional tone, or large follower count is not proof. Record why a source is suitable for the specific claim and note its limitations. If a source is biased, it may still be useful for understanding that source's position, but it should not be treated as neutral evidence for every claim.`, "Evaluate an official announcement, a news summary, and a promotional page for the same claim. Explain what each source can establish and what it cannot independently prove.", [["Identify the publisher", "Who is responsible for the content?"],["Inspect evidence", "Methods, references, data, and expertise"],["Consider purpose", "Inform, sell, persuade, entertain, or advocate?"],["State limitations", "What can this source reliably establish?"]], [["Does a professional-looking website prove accuracy?", "No; inspect authorship, evidence, purpose, and context", "Yes, design quality proves every claim", "Only if it has many images"],["What is a primary source?", "An original record or direct evidence relevant to the question", "Any article that appears first in search results", "A social post repeating another post"],["Can a promotional source ever be useful?", "Yes, for some facts about its own offering, while noting its limitations", "No source has any use if it is promotional", "Yes, it proves all superiority claims"]], "Match the source to the claim"),
      lesson("Verify claims across independent evidence", `Fact-checking means testing a specific claim against relevant evidence. Break compound statements into separate claims; one sentence may contain a date, a number, a comparison, and a causal explanation that require different checks. Find the original source when possible and read the surrounding context. Confirm that a quote has not been shortened in a misleading way and that a statistic measures what the writer says it measures.\n\nUse independent sources where appropriate. Three websites repeating the same press release are not three independent confirmations. Trace each report back to its origin and look for different evidence, methods, or direct records. For numbers, inspect the definition, population, sample size, collection period, units, and whether the figure is an estimate or a final result. For current claims, verify that the information is still valid today.\n\nEvidence can be mixed or incomplete. Record whether a claim is supported, contradicted, partly supported, outdated, or unverified, and explain why. Avoid turning absence of evidence into proof that something never happened. If a source cannot establish a claim, say so. Good fact-checking is careful about certainty: the strength of the conclusion should match the strength of the evidence.`, "Choose one factual claim and trace it to its original source. Find a second independent source, record the date and definition used, and classify the claim as supported, partly supported, contradicted, outdated, or unverified.", [["Separate claims", "Check each factual element individually"],["Trace origins", "Find the original evidence behind repeated reports"],["Compare", "Look for genuinely independent corroboration"],["Calibrate", "Make the conclusion no stronger than the evidence"]], [["Are three pages repeating the same press release independent confirmations?", "No; they may all rely on one origin", "Yes, every page is independent", "Yes, if their headlines differ"],["What should you check for a statistic?", "Definition, population, time period, units, and source", "Only whether it is a round number", "Only the chart colour"],["What does 'unverified' mean?", "The available evidence has not established the claim", "The claim is definitely false", "The claim is definitely true"]], "Follow evidence back to its origin"),
      lesson("Understand dates, context, images, and manipulated media", `A true statement can become misleading when its date, location, comparison group, or surrounding context is removed. An old announcement may be shared as if it happened today. A chart may show a sharp rise by starting its vertical axis at an unusual point. A quote may be accurate but omit the sentence that changes its meaning. Always ask what context a reasonable reader needs to interpret the claim.\n\nImages and videos also need verification. Search for earlier appearances of an image, inspect whether the caption matches the visible scene, and compare the claim with reliable reporting or official records. A photograph may be real but from a different event or country. Signs, weather, landmarks, clothing, and shadows can offer clues, but these clues should be treated as leads rather than proof. Be cautious about claiming that a person created or altered media without strong evidence.\n\nFor charts and numerical claims, read the axes, units, source, time range, sample size, and whether values are absolute or percentages. Percent change can sound dramatic when the starting number is tiny. A correlation between two events does not by itself prove that one caused the other. Context checking is especially important before sharing health, safety, election, financial, or emergency information.`, "Review a hypothetical viral post containing an old image and a dramatic percentage claim. List the checks you would perform before sharing it and explain what evidence would be enough to correct the caption.", [["Check time and place", "Does the media match the claimed event?"],["Inspect context", "Read the full quote, axes, and surrounding evidence"],["Verify independently", "Find credible reporting or original records"],["Share carefully", "Correct or withhold claims that remain uncertain"]], [["Can a real photograph have a misleading caption?", "Yes; it may come from another time or place", "No, a real image proves the caption", "Only if the image is blurry"],["What does correlation alone establish?", "That two things vary together, not necessarily that one caused the other", "That one event caused the other", "That both measurements are false"],["Why inspect a chart's axes and units?", "They affect how the numbers should be interpreted", "They are decorative", "The headline always provides all context"]], "Context is part of the evidence"),
      lesson("Use AI and automated tools without surrendering judgment", `AI tools can help generate search terms, summarize long material, organize notes, or suggest questions to investigate. They can also invent citations, mix up dates, omit caveats, and state uncertain information confidently. Treat generated text as a draft or lead, not as proof. A citation suggested by a tool must be opened and checked; a plausible title or URL is not evidence that a source exists or supports the claim.\n\nDo not paste confidential client information, private records, passwords, or sensitive personal data into an unapproved tool. Follow the organization's policy and disclose AI assistance when required. When using a summary, compare important claims with the original source, especially quotations, numbers, legal or medical information, and current policies. Preserve the distinction between what the source says and what the tool inferred.\n\nA useful workflow is to ask the tool for possible search terms, locate original sources yourself, verify the relevant passages, and write the final conclusion in your own words. Keep a record of sources and any material limitations. If a tool cannot provide a verifiable source, say that the claim remains unconfirmed rather than filling the gap with a guess.`, "Ask an AI tool to suggest search terms for a topic, then build a verification checklist. Explain which details must be checked against original sources and what information should never be pasted into an unapproved tool.", [["Use as assistant", "Generate leads or organize questions"],["Verify source", "Open and inspect the original evidence"],["Protect data", "Follow privacy and tool-use rules"],["Write responsibly", "Separate verified facts from suggestions"]], [["Should an AI-generated citation be trusted without opening it?", "No; verify that the source exists and supports the claim", "Yes, citations are always accurate", "Only if the title sounds professional"],["What should you do with confidential client data?", "Keep it out of unapproved tools and follow policy", "Paste it into any free tool", "Share it to improve the answer"],["What is a responsible use of AI in research?", "Use it to suggest leads, then verify evidence independently", "Let it invent missing facts", "Use its summary instead of all source checks"]], "Tools can assist; evidence must decide"),
      lesson("Cite sources and write a clear research brief", `A useful research brief allows another person to understand the conclusion and trace the evidence. Start with the question and a short answer, then explain the key findings, relevant dates, sources, limitations, and any recommended next step. Put the most decision-relevant information first. Use plain language and define technical terms when necessary. Do not bury an important uncertainty in a footnote.\n\nCitations should identify the source clearly enough for a reader to find it. Depending on the project, record the author or organization, title, publication or update date, URL, access date, and the specific page or section supporting the claim. Quote only when exact wording matters; otherwise summarize accurately in your own words and cite the source. Never make a source appear to support more than it actually says.\n\nSeparate fact from interpretation and recommendation. “The report recorded 120 responses” is a factual statement if supported by the report. “This proves everyone prefers option A” is an interpretation that may not be justified by that sample. State limitations, such as a small sample, missing data, or outdated information. A brief that admits its boundaries is more useful than one that sounds certain but hides weaknesses.`, "Write a 200–300 word research brief from three sources. Include the question, short answer, key evidence, citations, date checked, limitation, and one recommendation or unresolved question.", [["Answer first", "State the finding and its scope"],["Support", "Link each important claim to evidence"],["Qualify", "Explain uncertainty and limitations"],["Hand over", "Make sources and next steps easy to follow"]], [["What should a research brief do with an important limitation?", "State it clearly so the reader can judge the conclusion", "Hide it to sound confident", "Remove the source list"],["When is a direct quotation appropriate?", "When exact wording matters and it is accurately cited", "Whenever you want to avoid checking context", "When the source does not support your point"],["Why separate fact from recommendation?", "Readers need to know what evidence shows versus what you advise", "Recommendations are always facts", "It makes the brief longer without benefit"]], "Make the conclusion traceable")
    ],
    jobs: [job("FlexJobs", "https://www.flexjobs.com/", "Explore research and administrative listings; review fees and terms before paying.", "Browse listings")]
  },
  {
    slug: "freelance-work-readiness", title: "Freelance Work Readiness", category: "Career Foundations", level: "Beginner", minutes: 260, duration: "About 4 hours, plus planning practice", summary: "Prepare an honest service offer, define scope, communicate with clients, manage delivery, price thoughtfully, and recognize scams.",
    modules: [
      lesson("Understand freelancing and choose a realistic service", `Freelancing means offering services to clients as an independent worker rather than as a traditional employee. A freelancer may be paid for a defined project, a block of time, or ongoing work. The freedom to choose clients comes with responsibility: you must clarify expectations, organize time, keep records, protect client information, and manage periods when work is uncertain. Rules about taxes, registration, and contracts vary by location, so seek reliable local guidance when needed.\n\nA good beginner service is specific enough that a client can understand what they will receive. “I can help with anything online” is difficult to evaluate. “I will format up to 100 spreadsheet rows and check them against the supplied source” is clearer. Choose work you can practise and demonstrate honestly. If you are still learning, say so and start with a small task you can complete reliably rather than promising advanced expertise.\n\nMatch your offer to a real client need and your current ability. Identify the input you need, the deliverable you will provide, the likely time required, and what is excluded. A practice project can help you demonstrate your process, but label it as a sample rather than paid client work. Trust grows when your claims match your evidence.`, "Write two service offers based on a skill you can demonstrate. Each should identify the client need, exact deliverable, limit, and evidence you can show without claiming experience you do not have.", [["Identify a need", "What task does a client want completed?"],["Define the service", "Name a clear deliverable and boundary"],["Check readiness", "Can you demonstrate the skill honestly?"],["Show proof", "Use labelled practice work or real authorized work"]], [["Why is a specific service offer helpful?", "It lets the client understand the deliverable and judge fit", "It guarantees the client will hire you", "It removes the need to agree on scope"],["How should a beginner present a practice project?", "Label it honestly as a sample project", "Claim it was paid client work", "Hide how it was created"],["What should you do if a task exceeds your current ability?", "Clarify the requirement and avoid promising what you cannot deliver", "Promise it and hope", "Invent credentials"]], "Start with an honest, specific offer"),
      lesson("Build a portfolio that proves what you can do", `A portfolio is evidence of your ability, not just a gallery of attractive results. For each sample, explain the task, audience or problem, your approach, the tools used, and the result. A spreadsheet sample might show a before-and-after cleaning process; a writing sample might include the brief and the edited result; a design sample might show how the hierarchy changed after feedback. Keep the explanation concise but specific.\n\nYou can create realistic practice briefs when you do not yet have clients. Make the scenario clear and do not invent a real client, testimonial, sales result, or employment history. If you use public data, check its license and remove personal information. If you worked on a team project, state your contribution accurately. Never publish confidential work or a client's logo and information without permission.\n\nChoose a small number of relevant samples rather than filling a portfolio with unrelated work. A client should be able to find evidence matching the service you offer. Keep files readable, check links, and provide context for what the viewer should notice. Update the portfolio as your skills improve, and remove weak or outdated samples when stronger evidence becomes available.`, "Create a portfolio plan with three sample projects. For each, list the skill it demonstrates, what the viewer should inspect, and how you will label practice work honestly.", [["Choose relevant samples", "Match evidence to the service offered"],["Explain the work", "Brief, approach, tools, and result"],["Protect rights", "Get permission and remove private data"],["Present honestly", "Separate practice samples from paid work"]], [["What makes a portfolio sample useful?", "It demonstrates a relevant skill and explains the work", "It contains only decorative images", "It claims impressive results without evidence"],["Can a practice project be included in a portfolio?", "Yes, if it is clearly labelled as practice", "No one may ever show practice work", "Yes, but only if described as paid client work"],["What should you do before sharing client work?", "Check permission and remove confidential information", "Assume all client files are public", "Include every private detail to prove authenticity"]], "Show evidence, not invented experience"),
      lesson("Find opportunities and assess whether they are legitimate", `Freelance opportunities may come from trusted referrals, professional communities, job boards, marketplaces, or direct outreach. Read the task description carefully and check who is hiring, what the deliverable is, how payment works, and how the client communicates. A legitimate opportunity should allow reasonable questions about scope and terms. Be cautious of vague offers promising unusually high income for little work or pressuring you to act immediately.\n\nScams can involve upfront fees to unlock a job, fake checks or overpayments, requests to move money through your account, cryptocurrency transfers, purchasing equipment from a specified seller, or demands for passwords and verification codes. Never pay someone simply because they promise guaranteed work, and do not return an apparent overpayment before the payment is confirmed through your own bank or payment provider. Platform protections vary; understand their rules and fees.\n\nVerify identities through independent channels when possible. Be cautious when a supposed company uses a lookalike email domain, refuses a written scope, or asks to move off a platform before trust is established. Do not send identity documents or sensitive personal information unless there is a legitimate, verified reason and a safe process. If an offer feels suspicious, pause, save relevant messages, and seek advice before proceeding.`, "Assess three hypothetical job offers: one with a clear paid task, one asking for an upfront training fee, and one offering an overpayment cheque. Identify warning signs and the safest next step for each.", [["Verify", "Check identity, role, and communication channel"],["Read terms", "Scope, payment, deadlines, and fees"],["Spot pressure", "Upfront fees, money transfers, passwords, urgency"],["Pause safely", "Do not send money or sensitive data when uncertain"]], [["Which is a major warning sign?", "A demand for an upfront fee to guarantee a job", "A clear written task and agreed payment terms", "A reasonable question about your availability"],["What should you do with an apparent overpayment cheque?", "Verify it independently and do not return money before confirmation", "Immediately send the difference back", "Deposit it and assume funds are final"],["Should you share a login verification code with a recruiter?", "No; verification codes should remain private", "Yes, if the recruiter sounds confident", "Yes, if they promise quick payment"]], "Check the opportunity before investing effort"),
      lesson("Define scope, deliverables, and revisions", `Scope describes exactly what work is included. A clear agreement names the deliverable, quantity or size, format, deadline, inputs the client must provide, review process, number or type of revisions, price, and what is outside the agreement. “Design social media content” is vague; “prepare five square post graphics using supplied copy, deliver PNG exports and editable source files, and include one consolidated revision round” is more specific.\n\nScope protects both sides. If the client adds new tasks, changes the audience, or asks for several extra versions, the original agreement may no longer fit. Respond politely, explain the difference, and agree on a revised timeline or fee before doing extra work. Do not treat every request as unreasonable; some clarification and correction are normal. The key is to avoid silent assumptions that lead to disappointment.\n\nRecord decisions in writing through an agreed channel. For small projects, a clear message may be sufficient depending on local rules and the risk involved; larger or higher-risk work may require a formal contract. Make sure both sides understand when the work is considered accepted and how disputes will be handled. If a requirement is impossible or unsafe, explain the issue and propose an alternative rather than promising an unrealistic result.`, "Draft a scope for a small project in a skill you know. Specify deliverables, deadline, client inputs, revision limits, file formats, price basis, and what counts as additional work.", [["Define output", "What exactly will the client receive?"],["Set boundaries", "Quantity, formats, revisions, exclusions"],["Agree terms", "Timeline, inputs, price, and approval"],["Manage changes", "Confirm new work before proceeding"]], [["Why is 'do some design work' a weak scope?", "It leaves the deliverables and boundaries unclear", "It is too specific", "It guarantees shared expectations"],["What should happen when a client adds substantial new work?", "Discuss revised scope, timing, and price before proceeding", "Silently do it and hope", "Refuse every change automatically"],["Why record decisions in writing?", "It gives both sides a reference for what was agreed", "It guarantees no disagreement can happen", "It removes the need to communicate"]], "Agree on the work before doing the work"),
      lesson("Price your work and understand the real effort", `Pricing depends on the task, complexity, skill, time, value, risk, and local market. Common approaches include hourly pricing, a fixed project fee, or a retainer for agreed ongoing work. Hourly pricing links payment to time; a fixed fee gives the client a clearer project cost but requires a well-defined scope. Neither method is automatically best for every task.\n\nEstimate the full effort, not only the minutes spent producing the final file. Include reading the brief, asking questions, research, preparation, communication, revisions, quality checks, file delivery, and administration. If a task is new, create a small practice estimate and compare it with actual time. Over time, this helps you make more realistic quotes. Remember that revenue is not the same as take-home income; tools, platform fees, taxes, equipment, unpaid time, and other costs may apply.\n\nDo not invent market rates or promise outcomes you cannot control. Explain what the price includes and what would change it. If a client has a limited budget, you can offer a smaller scope rather than silently reducing quality or accepting an impossible deadline. For unfamiliar or substantial work, a paid discovery task or milestone arrangement may reduce risk, provided the terms are clear and lawful.`, "Estimate a hypothetical project by listing production, communication, research, revision, and delivery time. Compare hourly and fixed-fee approaches and explain the assumptions behind your quote.", [["Estimate effort", "Include hidden work and review time"],["Choose a model", "Hourly, fixed fee, or ongoing retainer"],["State assumptions", "Scope, revisions, timing, and costs"],["Review actuals", "Compare estimate with real time and improve"]], [["What should a project estimate include besides production?", "Research, communication, revisions, checks, and delivery", "Only the time spent clicking the final button", "No time for client questions"],["When is a fixed fee especially risky?", "When scope and revision expectations are unclear", "When deliverables are clearly defined", "When the deadline is agreed"],["What can you offer if the client's budget is too low?", "A smaller, clearly defined scope", "An impossible deadline at the same quality", "A guarantee of results outside your control"]], "Price with clear assumptions"),
      lesson("Communicate professionally and handle feedback", `Good client communication is clear, timely, respectful, and specific. Confirm that you understand the task, repeat key details when needed, and tell the client when they can expect an update. If a deadline is at risk, communicate early with the reason, the effect on delivery, and a realistic proposed plan. Disappearing until the deadline passes damages trust more than raising a problem early.\n\nAsk focused questions instead of sending a vague “What do you mean?” For example: “Should the report include only completed orders, or pending orders as well?” Summarize important decisions after a call so both sides have a shared record. Avoid promising instant replies at all hours unless that is genuinely part of the agreement. Set reasonable working hours and use an agreed channel for urgent issues.\n\nFeedback is information about how the result compares with expectations. Listen for the underlying problem, ask for an example if the request is unclear, and separate useful critique of the work from personal attacks. If you made a mistake, acknowledge it, correct it, and explain how you will prevent a repeat. If the request conflicts with the brief or requires additional work, discuss it calmly and refer to the agreed scope.`, "Write three client messages: a clarification question, an early warning that a deadline may slip, and a response to feedback asking for a clearer example. Keep each message professional and specific.", [["Confirm", "Repeat key requirements and dates"],["Update early", "Raise risks with a realistic plan"],["Listen", "Clarify feedback and identify the actual issue"],["Close the loop", "Confirm the correction or next action"]], [["What should you do when a deadline may be missed?", "Tell the client early and propose a realistic plan", "Wait until after the deadline", "Blame the client without explanation"],["What is a useful clarification question?", "A specific question about an ambiguous requirement", "A vague complaint about the brief", "A promise to guess silently"],["How should you respond to actionable feedback?", "Understand the issue, clarify if needed, and agree on a correction", "Treat every suggestion as a personal attack", "Change unrelated parts without telling the client"]], "Communication is part of the deliverable"),
      lesson("Deliver work, protect information, and keep records", `A reliable delivery process includes a final quality check, correct file names, the agreed format, and a concise handover. Check that the work matches the brief, links open, formulas or text are correct, and no drafts or private notes are accidentally included. If you are delivering several files, organize them so the client can tell which version is final. Explain what is included and identify anything still awaiting the client's input.\n\nProtect client information. Use approved storage and sharing methods, limit access to people who need it, and avoid public links for confidential files. Do not reuse client data in a portfolio without permission. Follow the agreed retention or deletion rules and local legal requirements. If you accidentally send the wrong file or expose information, report it promptly and follow the incident process rather than hoping nobody notices.\n\nKeep simple records of scope, approvals, delivery dates, invoices, expenses, and payments. These records help you track cash flow, understand how long projects take, and resolve misunderstandings. Administrative rules differ by location, so consult reliable local guidance about tax, registration, and recordkeeping obligations. A professional does not need an elaborate system at the beginning, but they do need a consistent one.`, "Design a project handover checklist and a basic recordkeeping table. Include scope, approval, files, delivery date, invoice status, expenses, and privacy checks.", [["Quality check", "Compare work with the brief"],["Package", "Use clear filenames and agreed formats"],["Protect", "Share only with authorized people"],["Record", "Keep approvals, invoices, and delivery details"]], [["What should a handover note include?", "Files delivered, checks completed, and open questions", "Only 'done' with no detail", "Private information unrelated to the task"],["Can client work automatically be added to a public portfolio?", "No; get permission and protect confidential information", "Yes, all paid work is public", "Yes, if the client has not noticed"],["Why keep basic project and payment records?", "They help manage delivery, money, and later questions", "They guarantee every client pays on time", "They remove all local legal obligations"]], "Finish reliably and protect trust"),
      lesson("Build a sustainable routine and learn from each project", `Freelance work includes more than client delivery. You may need to find opportunities, answer inquiries, plan projects, learn skills, manage finances, and rest. If every hour is treated as billable production time, you may underestimate the effort needed to keep the business running. Use a realistic calendar that includes administration, learning, and recovery time. Do not accept more work than you can complete responsibly.\n\nAfter a project, review what went well and what was difficult. Compare estimated time with actual time, note repeated client questions, identify errors that could be prevented with a checklist, and ask for feedback when appropriate. Use this information to improve your process and future estimates. A difficult project can teach you something, but repeated problems should lead to a change rather than simply becoming normal.\n\nSet boundaries around scope, response time, payment terms, and respectful communication. You can be helpful without agreeing to every urgent request. If a client repeatedly refuses agreed terms, asks for unsafe actions, or does not pay, keep records and follow the agreed dispute process or seek appropriate advice. Growth should mean better work and better judgment, not only more tasks.`, "Create a weekly routine with time for delivery, outreach, administration, learning, and rest. Add a short post-project review with one lesson and one process improvement.", [["Plan capacity", "Include delivery and non-billable work"],["Set boundaries", "Scope, availability, and payment terms"],["Review", "Compare estimates, outcomes, and feedback"],["Improve", "Turn repeated problems into a better process"]], [["Why should a freelancer reserve time for administration?", "Finding work, records, and communication are part of running the service", "Only delivery work exists", "Administration always takes zero time"],["What is a useful post-project review?", "Identify what worked and one concrete improvement", "Blame every problem on the client", "Ignore estimates and outcomes"],["Does being professional mean accepting every urgent request?", "No; set realistic boundaries and agree changes", "Yes, regardless of scope or safety", "Yes, even if the work cannot be completed"]], "Build a process that can improve over time")
    ],
    jobs: [job("Contra", "https://contra.com/opportunities", "Explore freelance opportunities and portfolio resources; review each client's terms.", "Browse opportunities")]
  }
];

// Keep dashboard counts aligned with the actual number of Basic Skills lessons.
for (const course of extraCourses) {
  course.moduleCount = course.modules.length;
}
